import AppKit
import CoreGraphics
import Foundation

// Notes, small postcards and stickers: text in decorative fonts, line-art frames and ornaments,
// an optional picture (from a file or generated by AI), and a cut contour for stickers.

// MARK: - Options

public enum CardKind: String, Codable, CaseIterable, Identifiable {
    case note, postcard, sticker
    public var id: String { rawValue }
    public var title: String {
        switch self { case .note: return String(localized: "Записка", bundle: .tinyPrinter); case .postcard: return String(localized: "Открытка", bundle: .tinyPrinter); case .sticker: return String(localized: "Стикер", bundle: .tinyPrinter) }
    }
    public var icon: String {
        switch self { case .note: return "note.text"; case .postcard: return "envelope.open"; case .sticker: return "seal" }
    }
}

public enum CardFrame: String, Codable, CaseIterable, Identifiable {
    case none, line, double, rounded, dashed, dotted, scallop, zigzag, ticket, corners, hearts, stars, snowflakes
    public var id: String { rawValue }
    public var title: String {
        switch self {
        case .none: return String(localized: "Без рамки", bundle: .tinyPrinter)
        case .line: return String(localized: "Линия", bundle: .tinyPrinter)
        case .double: return String(localized: "Двойная", bundle: .tinyPrinter)
        case .rounded: return String(localized: "Скруглённая", bundle: .tinyPrinter)
        case .dashed: return String(localized: "Пунктир (линия отреза)", bundle: .tinyPrinter)
        case .dotted: return String(localized: "Точки", bundle: .tinyPrinter)
        case .scallop: return String(localized: "Волна", bundle: .tinyPrinter)
        case .zigzag: return String(localized: "Зубчики (марка)", bundle: .tinyPrinter)
        case .ticket: return String(localized: "Билетик", bundle: .tinyPrinter)
        case .corners: return String(localized: "Уголки", bundle: .tinyPrinter)
        case .hearts: return String(localized: "Сердечки", bundle: .tinyPrinter)
        case .stars: return String(localized: "Звёздочки", bundle: .tinyPrinter)
        case .snowflakes: return String(localized: "Снежинки", bundle: .tinyPrinter)
        }
    }
    /// Dots the frame takes from each edge.
    var band: Int {
        switch self {
        case .none: return 0
        case .line, .dashed, .dotted, .rounded: return 10
        case .double: return 14
        case .corners: return 16
        case .scallop, .zigzag, .ticket: return 20
        case .hearts, .stars, .snowflakes: return 26
        }
    }
}

public enum CardOrnament: String, Codable, CaseIterable, Identifiable {
    case none, hearts, stars, sparkles, flowers, snowflakes, divider, dots
    public var id: String { rawValue }
    public var title: String {
        switch self {
        case .none: return String(localized: "Нет", bundle: .tinyPrinter)
        case .hearts: return String(localized: "Сердечки", bundle: .tinyPrinter)
        case .stars: return String(localized: "Звёзды", bundle: .tinyPrinter)
        case .sparkles: return String(localized: "Искорки", bundle: .tinyPrinter)
        case .flowers: return String(localized: "Цветочки", bundle: .tinyPrinter)
        case .snowflakes: return String(localized: "Снежинки", bundle: .tinyPrinter)
        case .divider: return String(localized: "Линия с ромбом", bundle: .tinyPrinter)
        case .dots: return String(localized: "Точки", bundle: .tinyPrinter)
        }
    }
}

public enum CardTitleStyle: String, Codable, CaseIterable, Identifiable {
    case plain, banner, underline
    public var id: String { rawValue }
    public var title: String {
        switch self {
        case .plain: return String(localized: "Обычный", bundle: .tinyPrinter)
        case .banner: return String(localized: "Лента (белым по чёрному)", bundle: .tinyPrinter)
        case .underline: return String(localized: "С росчерком снизу", bundle: .tinyPrinter)
        }
    }
}

public enum CardImagePlacement: String, Codable, CaseIterable, Identifiable {
    case top, afterTitle, bottom
    public var id: String { rawValue }
    public var title: String {
        switch self { case .top: return String(localized: "В начале", bundle: .tinyPrinter); case .afterTitle: return String(localized: "После заголовка", bundle: .tinyPrinter); case .bottom: return String(localized: "В конце", bundle: .tinyPrinter) }
    }
}

/// Decorative fonts that ship with macOS and cover Cyrillic.
public enum CardFonts {
    public static let all: [(name: String, title: String)] = [
        ("", String(localized: "Системный", bundle: .tinyPrinter)),
        ("SnellRoundhand-Bold", String(localized: "Каллиграфия (Snell)", bundle: .tinyPrinter)),
        ("SnellRoundhand-Black", String(localized: "Каллиграфия, жирная", bundle: .tinyPrinter)),
        ("SavoyeLetPlain", String(localized: "Изящный (Savoye)", bundle: .tinyPrinter)),
        ("SignPainter-HouseScriptSemibold", String(localized: "Вывеска (SignPainter)", bundle: .tinyPrinter)),
        ("Noteworthy-Bold", String(localized: "От руки (Noteworthy)", bundle: .tinyPrinter)),
        ("BradleyHandITCTT-Bold", String(localized: "От руки (Bradley)", bundle: .tinyPrinter)),
        ("ChalkboardSE-Bold", String(localized: "Мелом (Chalkboard)", bundle: .tinyPrinter)),
        ("MarkerFelt-Wide", String(localized: "Маркер", bundle: .tinyPrinter)),
        ("ComicSansMS-Bold", "Comic Sans"),
        ("AmericanTypewriter-Semibold", String(localized: "Печатная машинка", bundle: .tinyPrinter)),
        ("Georgia-Bold", String(localized: "Классика (Georgia)", bundle: .tinyPrinter)),
        ("PTSerif-Bold", "PT Serif"),
        ("Copperplate-Bold", String(localized: "Гравировка (Copperplate)", bundle: .tinyPrinter)),
        ("Phosphate-Inline", String(localized: "Афиша (Phosphate)", bundle: .tinyPrinter)),
        ("Luminari-Regular", String(localized: "Сказочный (Luminari)", bundle: .tinyPrinter)),
        ("Trattatello", String(localized: "Средневековый", bundle: .tinyPrinter)),
        ("AvenirNext-Heavy", String(localized: "Жирный гротеск", bundle: .tinyPrinter)),
    ]

    /// `sizePt` in typographic points; the font is returned in printer dots.
    public static func font(_ name: String, sizePt: Double) -> NSFont {
        let size = Units.dots(pt: max(4, sizePt))
        if !name.isEmpty, let f = NSFont(name: name, size: size) { return f }
        return NSFont.systemFont(ofSize: size, weight: .bold)
    }
}

// MARK: - Design

public struct CardDesign: Codable, Equatable {
    public var kind: CardKind = .postcard
    public var title = String(localized: "С днём рождения!", bundle: .tinyPrinter)
    public var titleFont = "SnellRoundhand-Bold"
    public var titleSizePt: Double = 26
    public var titleStyle: CardTitleStyle = .plain
    public var message = String(localized: "Пусть всё задуманное сбудется!", bundle: .tinyPrinter)
    public var messageFont = "Noteworthy-Bold"
    public var messageSizePt: Double = 13
    public var align: TextAlign = .center
    public var signature = ""
    public var frame: CardFrame = .scallop
    public var ornament: CardOrnament = .stars
    public var ornamentBottom = true
    /// A strip of "washi tape" across the top — for notes.
    public var tape = false
    /// Dotted lines under the message, like a notebook page.
    public var lined = false
    /// Extra empty lines to write on by hand (with `lined`).
    public var blankLines = 0
    public var imagePlacement: CardImagePlacement = .afterTitle
    public var imageWidthPercent: Double = 80
    /// nil = choose automatically (threshold for line art, dithering for photos).
    public var imageDither: DitherMethod?
    /// Crop white margins around the picture (AI pictures usually have a lot).
    public var imageTrim = true
    /// Contour around everything printed, to cut the sticker out with scissors.
    public var cutOutline = false
    public var lengthMM: Double = 0      // 0 = as long as the content needs
    public var paddingMM: Double = 2.5
    /// Several identical cards in one strip.
    public var repeatCount = 1

    public init() {}

    /// Everything off: the starting point for presets.
    public static var blank: CardDesign {
        var d = CardDesign()
        d.title = ""; d.message = ""; d.signature = ""
        d.frame = .none; d.ornament = .none; d.ornamentBottom = false
        d.titleStyle = .plain; d.align = .center
        return d
    }

    /// Switches the kind and adjusts decoration to suit it; texts, fonts and the picture stay.
    public func switched(to kind: CardKind) -> CardDesign {
        var d = self
        d.kind = kind
        switch kind {
        case .note:
            d.tape = true; d.lined = true; d.blankLines = max(d.blankLines, 2); d.cutOutline = false
            d.frame = .none; d.ornament = .none; d.align = .left; d.lengthMM = 0
        case .postcard:
            d.tape = false; d.lined = false; d.cutOutline = false; d.align = .center
            if d.frame == .none { d.frame = .scallop }
            if d.ornament == .none { d.ornament = .stars; d.ornamentBottom = true }
        case .sticker:
            d.tape = false; d.lined = false; d.cutOutline = true; d.frame = .none; d.ornament = .none
            d.align = .center; d.imageWidthPercent = 100; d.lengthMM = 0
        }
        return d
    }

    // MARK: Rendering

    public func render(width: Int, image: CGImage? = nil) -> MonoBitmap {
        let one = renderOne(width: width, image: image)
        guard repeatCount > 1 else { return one }
        var parts = [one]
        for _ in 1..<min(repeatCount, 50) {
            parts.append(cutOutline || frame != .none ? MonoBitmap(width: width, height: Units.dots(mm: 1.5)) : .cutLine(width: width))
            parts.append(one)
        }
        return .vstack(parts)
    }

    private func renderOne(width W: Int, image: CGImage?) -> MonoBitmap {
        let edge = 2
        let cutR = Units.dots(mm: 1.6), cutT = 2
        var pad = Units.dots(mm: paddingMM)
        if cutOutline { pad = max(pad, cutR + cutT + 3) }
        let side = edge + frame.band + pad
        let innerW = max(48, W - side * 2)
        let gap = Units.dots(mm: 1.8)
        let tapeH = 30
        let frameTop = tape ? edge + 12 : edge
        let contentTop = max(frameTop + frame.band + pad, tape ? tapeH + 12 : 0)
        let bottomPad = edge + frame.band + pad

        // nil marks where the picture goes; it is sized last so a fixed length can be honoured.
        var order: [MonoBitmap?] = []
        let has = { (s: String) in !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
        if ornament != .none { order.append(CardArt.ornamentRow(ornament, width: innerW)) }
        if image != nil && imagePlacement == .top { order.append(nil) }
        if has(title) { order.append(titleBlock(width: innerW)) }
        if image != nil && imagePlacement == .afterTitle { order.append(nil) }
        if has(message) || (lined && blankLines > 0) { order.append(messageBlock(width: innerW)) }
        if has(signature) { order.append(signatureBlock(width: innerW)) }
        if image != nil && imagePlacement == .bottom { order.append(nil) }
        if ornament != .none && ornamentBottom { order.append(CardArt.ornamentRow(ornament, width: innerW)) }

        let fixedH = lengthMM > 0 ? Units.dots(mm: lengthMM) : nil
        var picture: MonoBitmap?
        if let image {
            let others = order.compactMap { $0?.height }.reduce(0, +) + gap * max(0, order.count - 1)
            let maxH = fixedH.map { max(Units.dots(mm: 8), $0 - contentTop - bottomPad - others) }
            picture = imageBlock(image, width: innerW, maxHeight: maxH)
        }
        let blocks = order.compactMap { $0 ?? picture }.filter { $0.height > 0 }
        let contentH = blocks.reduce(0) { $0 + $1.height } + gap * max(0, blocks.count - 1)
        let H = max(fixedH ?? 0, contentTop + contentH + bottomPad, Units.dots(mm: 10))

        var content = MonoBitmap(width: W, height: H)
        var y = contentTop + max(0, (H - contentTop - bottomPad - contentH) / 2)
        for b in blocks {
            content.blit(b, x: side, y: y)
            y += b.height + gap
        }

        let canvas = Canvas(width: W, height: H)
        let rect = CGRect(x: edge, y: frameTop, width: W - edge * 2, height: H - frameTop - edge)
        CardArt.drawFrame(frame, in: rect, ctx: canvas.ctx)
        if tape {
            CardArt.drawTape(center: CGPoint(x: CGFloat(W) / 2, y: CGFloat(tapeH) / 2 + 5),
                             size: CGSize(width: min(150, CGFloat(W) * 0.42), height: CGFloat(tapeH)), ctx: canvas.ctx)
        }
        var out = canvas.gray.threshold(0.5)
        if cutOutline { out.blit(content.outline(distance: cutR, thickness: cutT), x: 0, y: 0) }
        out.blit(content, x: 0, y: 0)
        return out
    }

    private func titleBlock(width w: Int) -> MonoBitmap {
        // The ribbon's notch and padding take 0.8 × the font size on each side of the text.
        let font = CardArt.fitted(title, fontName: titleFont, sizePt: titleSizePt, width: CGFloat(w),
                                  sideInset: titleStyle == .banner ? 0.8 : 0)
        switch titleStyle {
        case .banner:
            return CardArt.banner(title, font: font, width: w)
        case .plain, .underline:
            let (bm, textW) = CardArt.textBlock(title, font: font, align: align, width: w)
            guard titleStyle == .underline else { return bm }
            let flourish = CardArt.flourish(width: w, length: min(CGFloat(w), textW * 0.9 + 24), align: align)
            return .vstack([bm, flourish], spacing: 3)
        }
    }

    private func messageBlock(width w: Int) -> MonoBitmap {
        let font = CardFonts.font(messageFont, sizePt: messageSizePt)
        if lined { return CardArt.linedBlock(message, font: font, align: align, width: w, blankLines: blankLines) }
        return CardArt.textBlock(message, font: font, align: align, width: w).0
    }

    private func signatureBlock(width w: Int) -> MonoBitmap {
        let font = CardFonts.font(messageFont, sizePt: messageSizePt * 0.8)
        return CardArt.textBlock(signature, font: font, align: kind == .sticker ? .center : .right, width: w).0
    }

    private func imageBlock(_ source: CGImage, width w: Int, maxHeight: Int?) -> MonoBitmap {
        let img = imageTrim ? CardArt.trimmedWhite(source) : source
        var iw = max(16, Int(Double(w) * min(100, max(10, imageWidthPercent)) / 100))
        var ih = max(1, Int((Double(img.height) * Double(iw) / Double(img.width)).rounded()))
        if let maxHeight, ih > maxHeight {
            ih = maxHeight
            iw = max(16, Int((Double(img.width) * Double(ih) / Double(img.height)).rounded()))
        }
        let gray = GrayImage(cgImage: img, width: iw, height: ih)
        let method = imageDither ?? (gray.midtoneRatio > 0.06 ? .atkinson : .threshold)
        let bm = method == .threshold
            ? gray.threshold(0.55)
            : gray.adjusted(brightness: 0.05, contrast: 0.12).sharpened(amount: 0.4).dithered(method)
        return bm.fitted(toWidth: w)
    }
}

// MARK: - Presets

public struct CardPreset: Identifiable {
    public let id: String
    public let title: String
    public let icon: String
    /// Suggested picture for the AI generator.
    public let prompt: String
    public let design: CardDesign

    init(_ id: String, _ title: String, icon: String, prompt: String, _ configure: (inout CardDesign) -> Void) {
        self.id = id; self.title = title; self.icon = icon; self.prompt = prompt
        var d = CardDesign.blank
        configure(&d)
        design = d
    }

    public static let all: [CardPreset] = [
        CardPreset("note", String(localized: "Записка", bundle: .tinyPrinter), icon: "note.text", prompt: String(localized: "котик спит, свернувшись клубочком", bundle: .tinyPrinter)) { d in
            d.kind = .note; d.tape = true; d.lined = true; d.blankLines = 2; d.align = .left
            d.message = String(localized: "Не забудь покормить кота!", bundle: .tinyPrinter); d.messageFont = "Noteworthy-Bold"; d.messageSizePt = 14
            d.imagePlacement = .bottom; d.imageWidthPercent = 45
        },
        CardPreset("todo", String(localized: "Список дел", bundle: .tinyPrinter), icon: "checklist", prompt: "") { d in
            d.kind = .note; d.lined = true; d.blankLines = 0; d.align = .left; d.frame = .dashed
            d.title = String(localized: "Сделать:", bundle: .tinyPrinter); d.titleFont = "Noteworthy-Bold"; d.titleSizePt = 20; d.titleStyle = .underline
            d.message = "☐ \n☐ \n☐ \n☐ "; d.messageFont = "Noteworthy-Bold"; d.messageSizePt = 14
        },
        CardPreset("birthday", String(localized: "День рождения", bundle: .tinyPrinter), icon: "birthday.cake", prompt: String(localized: "праздничный торт со свечками и воздушные шарики", bundle: .tinyPrinter)) { d in
