// MARK: - Drawing helpers

enum CardArt {
    static func attributed(_ text: String, font: NSFont, align: TextAlign, color: NSColor = .black,
                           lineHeight: CGFloat? = nil) -> NSAttributedString {
        let p = NSMutableParagraphStyle()
        p.alignment = align.ns
        p.lineBreakMode = .byWordWrapping
        if let lineHeight { p.minimumLineHeight = lineHeight; p.maximumLineHeight = lineHeight }
        return NSAttributedString(string: text, attributes: [.font: font, .paragraphStyle: p, .foregroundColor: color])
    }

    /// Shrinks the font only when a single word does not fit the width (long titles still wrap between words).
    /// Shrinks the font until the longest word fits on a line, so words never break in the middle
    /// (translations are often longer than the original). `sideInset` is per side, in font sizes.
    static func fitted(_ text: String, fontName: String, sizePt: Double, width: CGFloat, sideInset: CGFloat = 0) -> NSFont {
        let words = text.split(whereSeparator: { $0 == " " || $0.isNewline }).map(String.init)
        var pt = sizePt
        var font = CardFonts.font(fontName, sizePt: pt)
        for _ in 0..<3 {
            let room = width - 2 * sideInset * font.pointSize
            let widest = words.map { TextStyle.measure(attributed($0, font: font, align: .left)).width }.max() ?? 0
            guard widest > room, widest > 0, room > 0 else { return font }
            pt *= Double(room / widest) * 0.96
            font = CardFonts.font(fontName, sizePt: pt)
        }
        return font
    }

    /// Text rendered to ink only (swashes of script fonts are not clipped). Returns the bitmap and the text width.
    static func textBlock(_ text: String, font: NSFont, align: TextAlign, width w: Int) -> (MonoBitmap, CGFloat) {
        let s = attributed(text, font: font, align: align)
        let size = TextStyle.measure(s, maxWidth: CGFloat(w))
        let slack = ceil(font.pointSize * 0.4)
        let canvas = Canvas(width: w, height: Int(size.height + slack * 2))
        canvas.draw(s, in: CGRect(x: 0, y: slack, width: CGFloat(w), height: size.height + slack))
        return (canvas.gray.threshold(0.5).trimmedVertically(margin: 1), size.width)
    }

    /// Message on dotted notebook lines, plus empty lines to write on.
    static func linedBlock(_ text: String, font: NSFont, align: TextAlign, width w: Int, blankLines: Int) -> MonoBitmap {
        let lineH = ceil(font.pointSize * 1.6)
        let s = attributed(text, font: font, align: align, lineHeight: lineH)
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        let textLines = trimmed.isEmpty ? 0 : max(1, Int((TextStyle.measure(s, maxWidth: CGFloat(w)).height / lineH).rounded()))
        let total = textLines + max(0, blankLines)
        guard total > 0 else { return MonoBitmap(width: w, height: 0) }
        let canvas = Canvas(width: w, height: Int(lineH) * total + 4)
        if textLines > 0 { canvas.draw(s, in: CGRect(x: 0, y: 0, width: CGFloat(w), height: lineH * CGFloat(textLines) + 4)) }
        let ctx = canvas.ctx
        ctx.setFillColor(gray: 0, alpha: 1)
        for i in 0..<total {
            let y = lineH * CGFloat(i + 1) - 1
            var x: CGFloat = 1
            while x < CGFloat(w) - 1 {
                ctx.fill(CGRect(x: x, y: y, width: 2, height: 2))
                x += 6
            }
        }
        return canvas.gray.threshold(0.5)
    }

    /// White text on a black ribbon with notched ends.
    static func banner(_ text: String, font: NSFont, width w: Int) -> MonoBitmap {
        let notch = ceil(font.pointSize * 0.45)
        let hpad = ceil(font.pointSize * 0.35)
        let s = attributed(text, font: font, align: .center, color: .white)
        let size = TextStyle.measure(s, maxWidth: CGFloat(w) - 2 * (notch + hpad))
        let vpad = ceil(font.pointSize * 0.22)
        let h = size.height + vpad * 2
        let bw = min(CGFloat(w), size.width + 2 * (notch + hpad))
        let x0 = (CGFloat(w) - bw) / 2, x1 = x0 + bw
        let canvas = Canvas(width: w, height: Int(ceil(h)))
        let p = CGMutablePath()
        p.move(to: CGPoint(x: x0, y: 0))
        p.addLine(to: CGPoint(x: x1, y: 0))
        p.addLine(to: CGPoint(x: x1 - notch, y: h / 2))
        p.addLine(to: CGPoint(x: x1, y: h))
        p.addLine(to: CGPoint(x: x0, y: h))
        p.addLine(to: CGPoint(x: x0 + notch, y: h / 2))
        p.closeSubpath()
        canvas.ctx.addPath(p)
        canvas.ctx.setFillColor(gray: 0, alpha: 1)
        canvas.ctx.fillPath()
        canvas.draw(s, in: CGRect(x: x0 + notch + hpad, y: vpad, width: bw - 2 * (notch + hpad), height: size.height + 2))
        return canvas.gray.threshold(0.5)
    }

    /// A thin line with a diamond in the middle, under a title.
    static func flourish(width w: Int, length: CGFloat, align: TextAlign) -> MonoBitmap {
        let h: CGFloat = 12
        let canvas = Canvas(width: w, height: Int(h))
        let x0: CGFloat
        switch align {
        case .left: x0 = 0
        case .center: x0 = (CGFloat(w) - length) / 2
        case .right: x0 = CGFloat(w) - length
        }
        let mid = CGPoint(x: x0 + length / 2, y: h / 2)
        let ctx = canvas.ctx
        ctx.setStrokeColor(gray: 0, alpha: 1)
        ctx.setFillColor(gray: 0, alpha: 1)
        ctx.setLineWidth(2)
        ctx.setLineCap(.round)
        ctx.strokeLineSegments(between: [CGPoint(x: x0 + 2, y: mid.y), CGPoint(x: mid.x - 9, y: mid.y),
                                         CGPoint(x: mid.x + 9, y: mid.y), CGPoint(x: x0 + length - 2, y: mid.y)])
        ctx.addPath(diamond(center: mid, size: 10))
        ctx.fillPath()
        return canvas.gray.threshold(0.5)
    }

    // MARK: Motifs

    enum Motif { case heart, star, sparkle, flower, snowflake, dot, diamond }

    static func heart(center c: CGPoint, size s: CGFloat) -> CGPath {
        // x = 16 sin³t, y = 13 cos t − 5 cos 2t − 2 cos 3t − cos 4t: 32 units wide, y from −17 to 12.
        let k = s / 32
        let p = CGMutablePath()
        for i in 0...96 {
            let t = Double(i) / 96 * 2 * .pi
            let x = 16 * pow(sin(t), 3)
            let y = 13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t)
            let pt = CGPoint(x: c.x + CGFloat(x) * k, y: c.y - CGFloat(y + 2.5) * k)
            i == 0 ? p.move(to: pt) : p.addLine(to: pt)
        }
        p.closeSubpath()
        return p
    }

    static func star(center c: CGPoint, size s: CGFloat, points n: Int = 5, inner: CGFloat = 0.45) -> CGPath {
        let p = CGMutablePath()
        let r = s / 2
        for i in 0..<(n * 2) {
            let a = -CGFloat.pi / 2 + CGFloat(i) * .pi / CGFloat(n)
            let rr = i % 2 == 0 ? r : r * inner
            let pt = CGPoint(x: c.x + cos(a) * rr, y: c.y + sin(a) * rr)
            i == 0 ? p.move(to: pt) : p.addLine(to: pt)
        }
        p.closeSubpath()
        return p
    }

    static func diamond(center c: CGPoint, size s: CGFloat) -> CGPath {
        let p = CGMutablePath()
        p.addLines(between: [CGPoint(x: c.x, y: c.y - s / 2), CGPoint(x: c.x + s / 2, y: c.y),
                             CGPoint(x: c.x, y: c.y + s / 2), CGPoint(x: c.x - s / 2, y: c.y)])
        p.closeSubpath()
        return p
    }

    static func draw(_ motif: Motif, center c: CGPoint, size s: CGFloat, filled: Bool, ctx: CGContext) {
        ctx.saveGState()
        defer { ctx.restoreGState() }
        ctx.setFillColor(gray: 0, alpha: 1)
        ctx.setStrokeColor(gray: 0, alpha: 1)
        ctx.setLineWidth(max(1.6, s / 11))
        ctx.setLineCap(.round)
        ctx.setLineJoin(.round)
        let shape: CGPath
        switch motif {
        case .heart: shape = heart(center: c, size: s)
        case .star: shape = star(center: c, size: s)
        case .sparkle: shape = star(center: c, size: s, points: 4, inner: 0.28)
        case .diamond: shape = diamond(center: c, size: s)
        case .dot: shape = CGPath(ellipseIn: CGRect(x: c.x - s / 2, y: c.y - s / 2, width: s, height: s), transform: nil)
        case .flower:
            let petal = s * 0.2, dist = s * 0.28
            for i in 0..<5 {
                let a = -CGFloat.pi / 2 + CGFloat(i) * 2 * .pi / 5
                let pc = CGPoint(x: c.x + cos(a) * dist, y: c.y + sin(a) * dist)
                ctx.addEllipse(in: CGRect(x: pc.x - petal, y: pc.y - petal, width: petal * 2, height: petal * 2))
            }
            filled ? ctx.fillPath() : ctx.strokePath()
            let cr = s * 0.1
            ctx.setFillColor(gray: filled ? 1 : 0, alpha: 1)
            ctx.fillEllipse(in: CGRect(x: c.x - cr, y: c.y - cr, width: cr * 2, height: cr * 2))
            return
        case .snowflake:
            let r = s / 2
            var segs: [CGPoint] = []
            for i in 0..<6 {
                let a = CGFloat(i) * .pi / 3 - .pi / 2
                let tip = CGPoint(x: c.x + cos(a) * r, y: c.y + sin(a) * r)
                segs += [c, tip]
                let b = CGPoint(x: c.x + cos(a) * r * 0.55, y: c.y + sin(a) * r * 0.55)
                for side in [-1.0, 1.0] {
                    let ba = a + CGFloat(side) * .pi / 4
                    segs += [b, CGPoint(x: b.x + cos(ba) * r * 0.3, y: b.y + sin(ba) * r * 0.3)]
                }
            }
            ctx.strokeLineSegments(between: segs)
            return
        }
        ctx.addPath(shape)
        filled ? ctx.fillPath() : ctx.strokePath()
    }

    static func ornamentRow(_ ornament: CardOrnament, width w: Int) -> MonoBitmap {
        let h: CGFloat = 34
        let canvas = Canvas(width: w, height: Int(h))
        let ctx = canvas.ctx
        let cy = h / 2
        var items: [(Motif, CGFloat, Bool)] = []
        switch ornament {
        case .none: return MonoBitmap(width: w, height: 0)
        case .hearts: items = [(.heart, 13, false), (.heart, 19, true), (.heart, 27, true), (.heart, 19, true), (.heart, 13, false)]
        case .stars: items = [(.star, 12, true), (.star, 19, true), (.star, 28, true), (.star, 19, true), (.star, 12, true)]
        case .sparkles: items = [(.sparkle, 12, true), (.dot, 4, true), (.sparkle, 20, true), (.dot, 4, true), (.sparkle, 30, true),
                                 (.dot, 4, true), (.sparkle, 20, true), (.dot, 4, true), (.sparkle, 12, true)]
        case .flowers: items = [(.flower, 18, false), (.flower, 26, true), (.flower, 30, false), (.flower, 26, true), (.flower, 18, false)]
        case .snowflakes: items = [(.snowflake, 16, false), (.snowflake, 24, false), (.snowflake, 30, false), (.snowflake, 24, false), (.snowflake, 16, false)]
        case .divider:
            ctx.setStrokeColor(gray: 0, alpha: 1)
            ctx.setLineWidth(2)
            let mid = CGFloat(w) / 2
            let l0 = CGFloat(w) * 0.06, l1 = CGFloat(w) * 0.94
            ctx.strokeLineSegments(between: [CGPoint(x: l0, y: cy), CGPoint(x: mid - 20, y: cy),
                                             CGPoint(x: mid + 20, y: cy), CGPoint(x: l1, y: cy)])
            draw(.diamond, center: CGPoint(x: mid, y: cy), size: 18, filled: true, ctx: ctx)
            draw(.diamond, center: CGPoint(x: mid - 26, y: cy), size: 7, filled: true, ctx: ctx)
            draw(.diamond, center: CGPoint(x: mid + 26, y: cy), size: 7, filled: true, ctx: ctx)
            draw(.dot, center: CGPoint(x: l0, y: cy), size: 5, filled: true, ctx: ctx)
            draw(.dot, center: CGPoint(x: l1, y: cy), size: 5, filled: true, ctx: ctx)
            return canvas.gray.threshold(0.5)
        case .dots:
            let step: CGFloat = 16
            let n = Int((CGFloat(w) * 0.9) / step)
            let x0 = (CGFloat(w) - CGFloat(n - 1) * step) / 2
            for i in 0..<n { draw(.dot, center: CGPoint(x: x0 + CGFloat(i) * step, y: cy), size: i % 2 == 0 ? 5 : 3, filled: true, ctx: ctx) }
            return canvas.gray.threshold(0.5)
        }
        let spacing: CGFloat = 12
        let total = items.reduce(0) { $0 + $1.1 } + spacing * CGFloat(items.count - 1)
        var x = (CGFloat(w) - total) / 2
        for (m, s, filled) in items {
            draw(m, center: CGPoint(x: x + s / 2, y: cy), size: s, filled: filled, ctx: ctx)
            x += s + spacing
        }
        return canvas.gray.threshold(0.5)
    }

    // MARK: Frames

    /// Polyline arc (avoids CoreGraphics arc direction ambiguity in the flipped context).
    static func arc(_ p: CGMutablePath, center c: CGPoint, radius r: CGFloat, from a0: CGFloat, to a1: CGFloat) {
        let steps = max(6, Int(abs(a1 - a0) * r / 3))
        for i in 0...steps {
            let a = a0 + (a1 - a0) * CGFloat(i) / CGFloat(steps)
            p.addLine(to: CGPoint(x: c.x + cos(a) * r, y: c.y + sin(a) * r))
        }
    }

    static func drawFrame(_ frame: CardFrame, in R: CGRect, ctx: CGContext) {
        ctx.saveGState()
        defer { ctx.restoreGState() }
        ctx.setStrokeColor(gray: 0, alpha: 1)
        ctx.setFillColor(gray: 0, alpha: 1)
        ctx.setLineJoin(.round)
        ctx.setLineCap(.round)
        switch frame {
        case .none:
            break
        case .line:
            ctx.setLineWidth(3)
            ctx.stroke(R.insetBy(dx: 1.5, dy: 1.5))
        case .double:
            ctx.setLineWidth(4)
            ctx.stroke(R.insetBy(dx: 2, dy: 2))
            ctx.setLineWidth(1.5)
            ctx.stroke(R.insetBy(dx: 9, dy: 9))
        case .rounded:
            ctx.setLineWidth(3)
            ctx.addPath(CGPath(roundedRect: R.insetBy(dx: 1.5, dy: 1.5), cornerWidth: 22, cornerHeight: 22, transform: nil))
            ctx.strokePath()
        case .dashed:
            ctx.setLineWidth(2.5)
            ctx.setLineCap(.butt)
            ctx.setLineDash(phase: 0, lengths: [12, 8])
            ctx.stroke(R.insetBy(dx: 2, dy: 2))
        case .dotted:
            ctx.setLineWidth(5)
            ctx.setLineDash(phase: 0, lengths: [0, 11])
            ctx.addPath(CGPath(roundedRect: R.insetBy(dx: 3, dy: 3), cornerWidth: 14, cornerHeight: 14, transform: nil))
            ctx.strokePath()
        case .scallop:
            ctx.setLineWidth(3)
            ctx.addPath(scallop(R.insetBy(dx: 10, dy: 10), bump: 9))
            ctx.strokePath()
            ctx.setLineWidth(1.2)
            ctx.setLineDash(phase: 0, lengths: [3, 4])
            ctx.stroke(R.insetBy(dx: 17, dy: 17))
        case .zigzag:
            ctx.setLineWidth(2.5)
            ctx.addPath(zigzag(R.insetBy(dx: 8, dy: 8), tooth: 7))
            ctx.strokePath()
        case .ticket:
            ctx.setLineWidth(3)
            ctx.addPath(ticket(R.insetBy(dx: 2, dy: 2), corner: 14, notch: 14))
            ctx.strokePath()
            ctx.setLineWidth(1.5)
            ctx.setLineDash(phase: 0, lengths: [6, 5])
            ctx.addPath(ticket(R.insetBy(dx: 10, dy: 10), corner: 10, notch: 10))
            ctx.strokePath()
        case .corners:
            let L: CGFloat = 34
            let corners: [(CGPoint, CGFloat, CGFloat)] = [
                (CGPoint(x: R.minX + 2, y: R.minY + 2), 1, 1), (CGPoint(x: R.maxX - 2, y: R.minY + 2), -1, 1),
                (CGPoint(x: R.maxX - 2, y: R.maxY - 2), -1, -1), (CGPoint(x: R.minX + 2, y: R.maxY - 2), 1, -1),
            ]
            for (c, sx, sy) in corners {
                ctx.setLineWidth(3.5)
                ctx.strokeLineSegments(between: [CGPoint(x: c.x, y: c.y + sy * L), c, c, CGPoint(x: c.x + sx * L, y: c.y)])
                let d = CGPoint(x: c.x + sx * 7, y: c.y + sy * 7)
                ctx.setLineWidth(1.5)
                ctx.strokeLineSegments(between: [CGPoint(x: d.x, y: d.y + sy * L * 0.55), d, d, CGPoint(x: d.x + sx * L * 0.55, y: d.y)])
                draw(.diamond, center: CGPoint(x: c.x + sx * 14, y: c.y + sy * 14), size: 7, filled: true, ctx: ctx)
            }
        case .hearts, .stars, .snowflakes:
            let s: CGFloat = 20
            let Q = R.insetBy(dx: s / 2 + 1, dy: s / 2 + 1)
            for (i, p) in perimeterPoints(Q, spacing: s * 1.55).enumerated() {
                switch frame {
                case .hearts: draw(.heart, center: p, size: i % 2 == 0 ? s : s * 0.7, filled: i % 2 == 0, ctx: ctx)
                case .stars: draw(.star, center: p, size: i % 2 == 0 ? s : s * 0.6, filled: true, ctx: ctx)
                default:
                    if i % 2 == 0 { draw(.snowflake, center: p, size: s, filled: false, ctx: ctx) }
                    else { draw(.dot, center: p, size: 4, filled: true, ctx: ctx) }
                }
            }
        }
    }

    /// Evenly spaced points around a rectangle, each corner exactly once.
    static func perimeterPoints(_ Q: CGRect, spacing: CGFloat) -> [CGPoint] {
        let nx = max(1, Int((Q.width / spacing).rounded())), ny = max(1, Int((Q.height / spacing).rounded()))
        var pts: [CGPoint] = []
        for i in 0..<nx { pts.append(CGPoint(x: Q.minX + Q.width * CGFloat(i) / CGFloat(nx), y: Q.minY)) }
        for i in 0..<ny { pts.append(CGPoint(x: Q.maxX, y: Q.minY + Q.height * CGFloat(i) / CGFloat(ny))) }
        for i in 0..<nx { pts.append(CGPoint(x: Q.maxX - Q.width * CGFloat(i) / CGFloat(nx), y: Q.maxY)) }
        for i in 0..<ny { pts.append(CGPoint(x: Q.minX, y: Q.maxY - Q.height * CGFloat(i) / CGFloat(ny))) }
        return pts
    }

    /// Semicircles bulging outward along every edge (y grows downward).
    static func scallop(_ Q: CGRect, bump: CGFloat) -> CGPath {
        let p = CGMutablePath()
        let nx = max(2, Int((Q.width / (bump * 2)).rounded())), ny = max(2, Int((Q.height / (bump * 2)).rounded()))
        let rx = Q.width / CGFloat(nx) / 2, ry = Q.height / CGFloat(ny) / 2
        p.move(to: CGPoint(x: Q.minX, y: Q.minY))
        for i in 0..<nx { arc(p, center: CGPoint(x: Q.minX + rx * CGFloat(2 * i + 1), y: Q.minY), radius: rx, from: .pi, to: 2 * .pi) }
        for i in 0..<ny { arc(p, center: CGPoint(x: Q.maxX, y: Q.minY + ry * CGFloat(2 * i + 1)), radius: ry, from: -.pi / 2, to: .pi / 2) }
        for i in 0..<nx { arc(p, center: CGPoint(x: Q.maxX - rx * CGFloat(2 * i + 1), y: Q.maxY), radius: rx, from: 0, to: .pi) }
        for i in 0..<ny { arc(p, center: CGPoint(x: Q.minX, y: Q.maxY - ry * CGFloat(2 * i + 1)), radius: ry, from: .pi / 2, to: 3 * .pi / 2) }
        p.closeSubpath()
        return p
    }

    /// Triangular teeth pointing outward, like a postage stamp.
    static func zigzag(_ Q: CGRect, tooth t: CGFloat) -> CGPath {
        let p = CGMutablePath()
        let nx = max(2, Int((Q.width / (t * 2)).rounded())), ny = max(2, Int((Q.height / (t * 2)).rounded()))
        let sx = Q.width / CGFloat(nx), sy = Q.height / CGFloat(ny)
        p.move(to: CGPoint(x: Q.minX, y: Q.minY))
        for i in 0..<nx {
            p.addLine(to: CGPoint(x: Q.minX + sx * (CGFloat(i) + 0.5), y: Q.minY - t))
            p.addLine(to: CGPoint(x: Q.minX + sx * CGFloat(i + 1), y: Q.minY))
        }
        for i in 0..<ny {
            p.addLine(to: CGPoint(x: Q.maxX + t, y: Q.minY + sy * (CGFloat(i) + 0.5)))
            p.addLine(to: CGPoint(x: Q.maxX, y: Q.minY + sy * CGFloat(i + 1)))
        }
        for i in 0..<nx {
            p.addLine(to: CGPoint(x: Q.maxX - sx * (CGFloat(i) + 0.5), y: Q.maxY + t))
            p.addLine(to: CGPoint(x: Q.maxX - sx * CGFloat(i + 1), y: Q.maxY))
        }
        for i in 0..<ny {
            p.addLine(to: CGPoint(x: Q.minX - t, y: Q.maxY - sy * (CGFloat(i) + 0.5)))
            p.addLine(to: CGPoint(x: Q.minX, y: Q.maxY - sy * CGFloat(i + 1)))
        }
        p.closeSubpath()
        return p
    }

    /// Rectangle with concave corners and a round notch in the middle of each side.
    static func ticket(_ Q: CGRect, corner c: CGFloat, notch n: CGFloat) -> CGPath {
        let p = CGMutablePath()
        let midY = Q.midY
        p.move(to: CGPoint(x: Q.minX + c, y: Q.minY))
        p.addLine(to: CGPoint(x: Q.maxX - c, y: Q.minY))
        arc(p, center: CGPoint(x: Q.maxX, y: Q.minY), radius: c, from: .pi, to: .pi / 2)
        p.addLine(to: CGPoint(x: Q.maxX, y: midY - n))
        arc(p, center: CGPoint(x: Q.maxX, y: midY), radius: n, from: -.pi / 2, to: -3 * .pi / 2)
        p.addLine(to: CGPoint(x: Q.maxX, y: Q.maxY - c))
        arc(p, center: CGPoint(x: Q.maxX, y: Q.maxY), radius: c, from: -.pi / 2, to: -.pi)
        p.addLine(to: CGPoint(x: Q.minX + c, y: Q.maxY))
        arc(p, center: CGPoint(x: Q.minX, y: Q.maxY), radius: c, from: 0, to: -.pi / 2)
        p.addLine(to: CGPoint(x: Q.minX, y: midY + n))
        arc(p, center: CGPoint(x: Q.minX, y: midY), radius: n, from: .pi / 2, to: -.pi / 2)
        p.addLine(to: CGPoint(x: Q.minX, y: Q.minY + c))
        arc(p, center: CGPoint(x: Q.minX, y: Q.minY), radius: c, from: .pi / 2, to: 0)
        p.closeSubpath()
        return p
    }

    /// A slightly rotated strip of hatched "washi tape" with torn ends.
    static func drawTape(center c: CGPoint, size: CGSize, ctx: CGContext) {
        ctx.saveGState()
        defer { ctx.restoreGState() }
        ctx.translateBy(x: c.x, y: c.y)
        ctx.rotate(by: -0.06)
        let w = size.width / 2, h = size.height / 2
        let p = CGMutablePath()
        p.move(to: CGPoint(x: -w, y: -h))
        p.addLine(to: CGPoint(x: w, y: -h))
        let teeth = 5
        for i in 0..<teeth {
            let y0 = -h + size.height * CGFloat(i) / CGFloat(teeth)
            p.addLine(to: CGPoint(x: w - 4, y: y0 + size.height / CGFloat(teeth) / 2))
            p.addLine(to: CGPoint(x: w, y: y0 + size.height / CGFloat(teeth)))
        }
        p.addLine(to: CGPoint(x: -w, y: h))
        for i in 0..<teeth {
            let y0 = h - size.height * CGFloat(i) / CGFloat(teeth)
            p.addLine(to: CGPoint(x: -w + 4, y: y0 - size.height / CGFloat(teeth) / 2))
            p.addLine(to: CGPoint(x: -w, y: y0 - size.height / CGFloat(teeth)))
        }
        p.closeSubpath()
        ctx.addPath(p)
        ctx.setFillColor(gray: 1, alpha: 1)
        ctx.fillPath()
        ctx.saveGState()
        ctx.addPath(p)
        ctx.clip()
        ctx.setStrokeColor(gray: 0, alpha: 1)
        ctx.setLineWidth(2)
        var x = -w - size.height
        var segs: [CGPoint] = []
        while x < w {
            segs += [CGPoint(x: x, y: h), CGPoint(x: x + size.height, y: -h)]
            x += 7
        }
        ctx.strokeLineSegments(between: segs)
        ctx.restoreGState()
        ctx.addPath(p)
        ctx.setStrokeColor(gray: 0, alpha: 1)
        ctx.setLineWidth(2)
        ctx.strokePath()
    }

    // MARK: Images

    /// Crops near-white margins (keeps a small border).
    static func trimmedWhite(_ img: CGImage) -> CGImage {
        let probe = GrayImage(cgImage: img, targetWidth: min(img.width, 400))
        var minX = probe.width, minY = probe.height, maxX = -1, maxY = -1
        for y in 0..<probe.height {
            for x in 0..<probe.width where probe.data[y * probe.width + x] < 0.88 {
                minX = min(minX, x); maxX = max(maxX, x); minY = min(minY, y); maxY = max(maxY, y)
            }
        }
        guard maxX > minX, maxY > minY else { return img }
        let sx = Double(img.width) / Double(probe.width), sy = Double(img.height) / Double(probe.height)
        let m = 0.03 * Double(max(maxX - minX, maxY - minY))
        let r = CGRect(x: (Double(minX) - m) * sx, y: (Double(minY) - m) * sy,
                       width: (Double(maxX - minX + 1) + 2 * m) * sx, height: (Double(maxY - minY + 1) + 2 * m) * sy)
            .intersection(CGRect(x: 0, y: 0, width: img.width, height: img.height)).integral
        return img.cropping(to: r) ?? img
    }
}

// MARK: - Bitmap composition

public extension MonoBitmap {
    /// Draws `src` on top (black wins).
    mutating func blit(_ src: MonoBitmap, x ox: Int, y oy: Int) {
        for sy in 0..<src.height {
            let ty = oy + sy
            guard ty >= 0 && ty < height else { continue }
            let sBase = sy * src.width, tBase = ty * width
            for sx in 0..<src.width where src.pixels[sBase + sx] != 0 {
                let tx = ox + sx
                if tx >= 0 && tx < width { pixels[tBase + tx] = 1 }
            }
        }
    }

    /// A contour `distance` dots outside everything black, for cutting a sticker out with scissors.
    /// Holes are ignored and narrow gaps (between rays, letters) are bridged by a morphological closing of
    /// radius `smooth`, so the line is easy to follow.
    func outline(distance r: Int, thickness t: Int, smooth: Int = Units.dots(mm: 4)) -> MonoBitmap {
        guard width > 0, height > 0 else { return self }
        let big = max(r, smooth)
        // Work on a padded copy so growing near the edges is not clipped.
        let m = big + t + 2
        let w = width + 2 * m, h = height + 2 * m
        var mask = [Bool](repeating: false, count: w * h)
        for y in 0..<height {
            for x in 0..<width where pixels[y * width + x] != 0 { mask[(y + m) * w + x + m] = true }
        }
        // Dilate by `big`.
        let near = Self.chamfer(mask, w, h)
        let grown = near.map { $0 <= Int32(big * 3) }
        // Flood the background from the border; whatever it cannot reach is inside the shape (fills holes).
        var outside = [Bool](repeating: false, count: w * h)
        var stack: [Int] = []
        for i in 0..<(w * h) {
            let x = i % w, y = i / w
            if (x == 0 || y == 0 || x == w - 1 || y == h - 1) && !grown[i] { outside[i] = true; stack.append(i) }
        }
        while let i = stack.popLast() {
            let x = i % w, y = i / w
            for j in [x > 0 ? i - 1 : -1, x < w - 1 ? i + 1 : -1, y > 0 ? i - w : -1, y < h - 1 ? i + w : -1]
            where j >= 0 && !grown[j] && !outside[j] {
                outside[j] = true
                stack.append(j)
            }
        }
        // Erode back by big − r: the shape now sits `r` outside the ink, with concave gaps bridged.
        let toOutside = Self.chamfer(outside, w, h)
        let shape = toOutside.map { $0 > Int32((big - r) * 3) }
        let toEdge = Self.chamfer(shape.map { !$0 }, w, h)
        var out = MonoBitmap(width: width, height: height)
        for y in 0..<height {
            for x in 0..<width {
                let i = (y + m) * w + x + m
                if shape[i] && toEdge[i] <= Int32(t * 3) { out.pixels[y * width + x] = 1 }
            }
        }
        return out
    }

    /// 3-4 chamfer distance (×3) to the nearest `true` cell.
    internal static func chamfer(_ seeds: [Bool], _ w: Int, _ h: Int) -> [Int32] {
        let inf: Int32 = 1 << 28
        var d = seeds.map { $0 ? Int32(0) : inf }
        for y in 0..<h {
            for x in 0..<w {
                let i = y * w + x
                var v = d[i]
                if v == 0 { continue }
                if x > 0 { v = min(v, d[i - 1] + 3) }
                if y > 0 {
                    v = min(v, d[i - w] + 3)
                    if x > 0 { v = min(v, d[i - w - 1] + 4) }
                    if x < w - 1 { v = min(v, d[i - w + 1] + 4) }
                }
                d[i] = v
            }
        }
        for y in stride(from: h - 1, through: 0, by: -1) {
            for x in stride(from: w - 1, through: 0, by: -1) {
                let i = y * w + x
                var v = d[i]
                if v == 0 { continue }
                if x < w - 1 { v = min(v, d[i + 1] + 3) }
                if y < h - 1 {
                    v = min(v, d[i + w] + 3)
                    if x < w - 1 { v = min(v, d[i + w + 1] + 4) }
                    if x > 0 { v = min(v, d[i + w - 1] + 4) }
                }
                d[i] = v
            }
        }
        return d
    }
}
